'use strict';
let sharedRevision=0,sharedBase=null,sharedStatus='connecting',pendingChanges=false,saving=false,pulling=false,equipmentDirty=false;
const DRAFT_KEY=KEY+'-pending-shared',MIGRATION_KEY=KEY+'-migration',CACHE_KEY=KEY+'-shared-cache';
const copyData=x=>JSON.parse(JSON.stringify(x));
function novaDraftStorageKey(key){const user=typeof novaCurrentUser==='function'?novaCurrentUser():null;return user&&(key===DRAFT_KEY||key==='nova-alianca-draft-owner')?key+'-'+user.id:key}
function localRemove(key){try{localStorage.removeItem(novaDraftStorageKey(key))}catch{}}
function localRead(key){try{return localStorage.getItem(novaDraftStorageKey(key))}catch{return null}}
function localWrite(key,value){if(key===CACHE_KEY)return true;try{localStorage.setItem(novaDraftStorageKey(key),JSON.stringify(value));return true}catch{toast('O navegador não conseguiu guardar uma cópia local. Exporte um backup se a conexão falhar.');return false}}
function sharedNotice(){return pendingChanges?`<div class="notice"><div><strong>Há alterações ainda não salvas na empresa.</strong><p>Elas estão preservadas neste aparelho. Tente novamente ou exporte antes de atualizar.</p></div><div class="actions">${btn('retry-save','Tentar salvar','', 'primary')}${btn('recover-shared','Exportar pendências e atualizar')}</div></div>`:''}
function setSharedStatus(value){sharedStatus=value;const node=document.getElementById('sync-label');if(node)node.textContent=value==='online'?(novaAuth.session?.hosted?'Sincronizado online':'Sincronizado na LAN'):value==='saving'?'Salvando na empresa…':'Sem conexão com o servidor'}
async function requestShared(url,options={}){const controller=new AbortController(),token=novaCaptureSession();novaAuth.requests.add(controller);const timer=setTimeout(()=>controller.abort(),15000);const stale=()=>{if(!novaSessionCurrent(token))throw Object.assign(Error('Sua conta mudou. A resposta anterior foi descartada.'),{staleSession:true})};try{const response=await fetch(url,{cache:'no-store',...options,headers:{...(options.headers||{}),...(novaAuth.session?.csrf?{'X-CSRF-Token':novaAuth.session.csrf}:{})},signal:controller.signal});stale();if(response.status===304)return null;let data;try{data=await response.json()}catch{stale();throw Error(novaAuth.session?.hosted?'O servidor não respondeu corretamente. Aguarde e tente novamente.':'Não foi possível consultar o servidor. Tente novamente.')}stale();if(!response.ok){if(response.status===401&&novaAuth.stage==='ready')novaExpired();const err=Error(data.error||'Não foi possível conectar ao servidor da empresa.');err.status=response.status;throw err}return data}catch(error){if(!novaSessionCurrent(token)&&error.status!==401)throw Object.assign(Error('Sua conta mudou. A operação anterior foi encerrada.'),{staleSession:true});if(error.name==='AbortError')throw Error('A conexão demorou. Confira o estado da operação antes de repetir.');throw error}finally{clearTimeout(timer);novaAuth.requests.delete(controller)}}
function adoptShared(snapshot){state=validateData(snapshot.data);state.demo=false;state.profiles=state.profiles||[];sharedSupportsProfiles=!!snapshot.capabilities?.profiles;sharedRevision=snapshot.revision;sharedBase=copyData(state);localWrite(CACHE_KEY,snapshot);setSharedStatus('online')}
function novaOwnsDraft(){try{const owner=JSON.parse(localRead('nova-alianca-draft-owner')||'null'),user=novaCurrentUser();return !!(owner&&user&&owner.id===user.id&&owner.username===user.username)}catch{return false}}
function migrationFingerprint(text){let hash=2166136261;for(let i=0;i<text.length;i++)hash=Math.imul(hash^text.charCodeAt(i),16777619);return text.length+':'+(hash>>>0)}
async function bootShared(){
 const token=novaCaptureSession();try{
  let snapshot=await requestShared('/api/fleet');
  const legacy=localRead(KEY);
  try{if(legacy){const fingerprint=migrationFingerprint(legacy);if(localStorage.getItem(MIGRATION_KEY)!==fingerprint){const old=validateData(JSON.parse(legacy));old.vehicles=old.vehicles.filter(v=>!(String(v.chassis).startsWith('9BMDEMO00')&&String(v.gearbox).startsWith('EXEMPLO-')));if(old.vehicles.length){snapshot=await requestShared('/api/migrate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:old})});if(snapshot.migration?.conflicts)toast('Dados antigos incorporados. Há divergências preservadas no backup do servidor para conferência.')}localStorage.setItem(MIGRATION_KEY,fingerprint)}}}catch(error){if(error.staleSession||!novaSessionCurrent(token))return;toast('Os dados antigos deste navegador precisam de conferência e foram preservados. A frota da empresa está disponível.')} 
  if(!novaSessionCurrent(token))return;adoptShared(snapshot);
  try{const owner=JSON.parse(localStorage.getItem('nova-alianca-draft-owner')||'null'),user=novaCurrentUser(),legacy=localStorage.getItem(DRAFT_KEY);if(legacy&&owner?.id===user?.id&&owner?.username===user?.username&&!localRead(DRAFT_KEY)){if(localWrite(DRAFT_KEY,JSON.parse(legacy))&&localWrite('nova-alianca-draft-owner',owner)){localStorage.removeItem(String(DRAFT_KEY));localStorage.removeItem(String('nova-alianca-draft-owner'))}}}catch{}
  const rawDraft=localRead(DRAFT_KEY);if(rawDraft&&novaOwnsDraft()){const draft=JSON.parse(rawDraft);state=validateData(draft.data);sharedBase=validateData(draft.base);sharedRevision=draft.revision;pendingChanges=true;await saveShared()}
  shell();startSharedUpdates();ensureProfileChoice();
 }catch(error){if(error.staleSession||!novaSessionCurrent(token))return;setSharedStatus('offline');const app=document.getElementById('app');app.innerHTML=`<main style="max-width:680px;margin:60px auto;padding:24px"><h1>Conectar à frota da empresa</h1><p class="sub">${esc(error.message)}</p>${novaAuth.session?.hosted?'<p>Confira a conexão com a internet e tente novamente. Nenhum salvamento é confirmado sem resposta do servidor.</p>':'<p>Se o CMD já estava aberto antes desta atualização, feche a janela e abra <strong>iniciar-lan.cmd</strong> novamente.</p>'}<p>Os dados anteriores deste aparelho foram preservados.</p>${btn('reconnect','Tentar conectar','', 'primary')}</main>`}
}
async function saveShared(){
 pendingChanges=true;setSharedStatus('saving');const draft={revision:sharedRevision,base:copyData(sharedBase),data:copyData(state)};localWrite(DRAFT_KEY,draft);if(typeof novaCurrentUser==='function'&&novaCurrentUser())localWrite('nova-alianca-draft-owner',{id:novaCurrentUser().id,username:novaCurrentUser().username});
 try{const snapshot=await requestShared('/api/fleet',{method:'PUT',headers:{'Content-Type':'application/json','X-Alinho-Profile':activeProfileId||''},body:JSON.stringify(draft)});adoptShared(snapshot);pendingChanges=false;try{localRemove(DRAFT_KEY);localRemove('nova-alianca-draft-owner')}catch{}return true}
 catch(error){if(error.staleSession)return false;setSharedStatus('offline');toast(error.status===409?'Outro aparelho alterou o mesmo dado. Exporte as pendências e atualize a frota antes de refazer essa alteração.':error.message);return false}
}
function canRefreshShared(){return !saving&&!pendingChanges&&!equipmentDirty&&!document.getElementById('modal').open&&!document.activeElement?.matches('input,select,textarea')}
async function pullShared(){const token=novaCaptureSession();if(typeof novaAuth!=='undefined'&&(novaAuth.stage!=='ready'||novaCurrentUser()?.role==='employee'))return;if(pulling||!canRefreshShared())return;pulling=true;try{const snapshot=await requestShared('/api/fleet',{headers:{'If-None-Match':`"${sharedRevision}"`}});setSharedStatus('online');if(snapshot&&snapshot.revision!==sharedRevision){adoptShared(snapshot);const scroll=window.scrollY;shell();window.scrollTo(0,scroll)}}catch{if(novaSessionCurrent(token))setSharedStatus('offline')}finally{if(novaSessionCurrent(token))pulling=false}}
let sharedUpdatesStarted=false;
function startSharedUpdates(){if(!novaAuth.session?.hosted&&typeof EventSource!=='undefined'&&!novaAuth.fleetEvents){const events=new EventSource('/api/events');novaAuth.fleetEvents=events;events.addEventListener('fleet',pullShared);events.onerror=()=>{if(novaAuth.stage==='ready'&&novaCurrentUser()?.role!=='employee')setSharedStatus('offline')}}if(sharedUpdatesStarted)return;sharedUpdatesStarted=true;setInterval(()=>{if(document.visibilityState==='visible')pullShared()},4000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')pullShared()});document.addEventListener('input',e=>{if(e.target.closest?.('#equipment-form'))equipmentDirty=true});document.addEventListener('change',e=>{if(e.target.closest?.('#equipment-form'))equipmentDirty=true})}
async function recoverShared(){exportData();localWrite(DRAFT_KEY+'-recovered-'+Date.now(),{data:state,base:sharedBase,revision:sharedRevision});const snapshot=await requestShared('/api/fleet');adoptShared(snapshot);pendingChanges=false;try{localStorage.removeItem(DRAFT_KEY);localStorage.removeItem('nova-alianca-draft-owner')}catch{}shell();toast('Pendências exportadas. Dados atuais da empresa carregados.')}
// Inicialização feita após carregar as adaptações de experiência.
